@@ -159,4 +159,83 @@ class ReservationServiceTest {
     void anUnknownReservationIsNotFound() {
         assertEquals(ErrorCode.RESERVATION_NOT_FOUND, errorOf(() -> service.find(42)));
     }
+
+    private static NewReservation corporateStay(String companyCode) {
+        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
+        return new NewReservation(201, guest, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 2,
+                RatePlan.CORPORATE, companyCode);
+    }
+
+    @Test
+    void corporatePlanDiscountsByCompanyAndRefundsEverything() {
+        Reservation reservation = service.create(corporateStay("TECNOSUL"));
+
+        assertEquals(new BigDecimal("779.80"), reservation.price().subtotal());
+        assertEquals(new BigDecimal("93.58"), reservation.price().discount());
+        assertEquals(new BigDecimal("686.22"), reservation.price().total());
+        service.confirm(reservation.id());
+        assertEquals(new BigDecimal("686.22"), service.cancel(reservation.id()).refund());
+    }
+
+    @Test
+    void corporatePlanDiscountsOfTheOtherCompanies() {
+        Reservation agrovale = service.create(corporateStay("AGROVALE"));
+        assertEquals(new BigDecimal("140.36"), agrovale.price().discount());
+        service.cancel(agrovale.id());
+        assertEquals(new BigDecimal("194.95"), service.create(corporateStay("FARMAVIDA")).price().discount());
+    }
+
+    @Test
+    void corporatePlanNeedsAKnownCompanyCode() {
+        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(corporateStay(null))));
+        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(corporateStay("OUTRA"))));
+        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(corporateStay("tecnosul"))));
+    }
+
+    @Test
+    void weekendPackageIsAClosedPriceAndRefundsHalf() {
+        Reservation reservation = service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));
+
+        assertEquals(2, reservation.price().nights());
+        assertEquals(new BigDecimal("820.00"), reservation.price().subtotal());
+        assertEquals(new BigDecimal("0.00"), reservation.price().discount());
+        assertEquals(new BigDecimal("820.00"), reservation.price().total());
+        service.confirm(reservation.id());
+        assertEquals(new BigDecimal("410.00"), service.cancel(reservation.id()).refund());
+    }
+
+    @Test
+    void weekendPackageHasTheSamePriceInHighSeason() {
+        assertEquals(new BigDecimal("520.00"),
+                service.create(stay(101, "2027-07-09", "2027-07-11", 2, RatePlan.WEEKEND_PACKAGE)).price().total());
+        assertEquals(new BigDecimal("1200.00"),
+                service.create(stay(301, "2027-07-09", "2027-07-11", 2, RatePlan.WEEKEND_PACKAGE)).price().total());
+    }
+
+    @Test
+    void weekendPackageOnlyFromFridayToSunday() {
+        assertEquals(ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(201, "2027-03-11", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
+        assertEquals(ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-15", 2, RatePlan.WEEKEND_PACKAGE))));
+        assertEquals(ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
+    }
+
+    @Test
+    void longStayTakes10PercentOffAndRefundsEverything() {
+        Reservation reservation = service.create(stay(101, "2027-03-01", "2027-03-08", 2, RatePlan.LONG_STAY));
+
+        assertEquals(new BigDecimal("1749.30"), reservation.price().subtotal());
