    18	    public Price calculate(Room room, NewReservation request) {
    19	        LocalDate checkIn = request.checkIn();
    20	        LocalDate checkOut = request.checkOut();
    21	        int nights = 0;
    22	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    23	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    24	            subtotal = subtotal.add(nightPrice(room, night));
    25	            nights++;
    26	        }
    27	        Price nightsPrice = new Price(nights, subtotal, cents(BigDecimal.ZERO), subtotal);
    28	        return request.ratePlan().price(room, request, nightsPrice);
    29	    }
    30	
    31	    BigDecimal nightPrice(Room room, LocalDate night) {
    32	        BigDecimal nightlyRate = room.nightlyRate();
    33	        if (isHighSeason(night)) {
    34	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    35	        }
    36	        return cents(nightlyRate);
    37	    }
