    39	    /** High season: from December 15 to the end of February, and the whole of July. */
    40	    static boolean isHighSeason(LocalDate date) {
    41	        Month month = date.getMonth();
    42	        return month == Month.JANUARY
    43	                || month == Month.FEBRUARY
    44	                || month == Month.JULY
    45	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    46	    }
    47	
    48	    static BigDecimal cents(BigDecimal value) {
    49	        return value.setScale(2, RoundingMode.HALF_EVEN);
    50	    }
